#include <stdio.h>

char a[5][5] = {"0010", "1111", "1100", "0111"};
int b;

void f(int p, int q, int r) {
    if(p < 0 || q < 0 || p >= 4 || q >= 4) return;
    if(a[p][q] == '0') return;
    b += r;

    a[p][q] = '0';
    f(p-1, q, r+1);
    f(p+1, q, r+1);
    f(p, q-1, r+1);
    f(p, q+1, r+1);
}

int main()
{
    for(int i=0 ; i<4 ; i++) {
        for(int j=0 ; j<4 ; j++) {
            if(a[i][j] == '1') {
                f(i, j, 1);
            }
        }
    }
    printf("%d\n", b);
    return 0;
}

#include <stdio.h>

#define M(A, B) (A > B ? B : A)
#define N(A, B) (A ^ B == 0)
#define P(A, B) (A > B ? A : B)

int n, m;
int mapp[8][8];

int main(void) {
    int f = 1;
    scanf("%d %d", &n, &m);

    for(int i=0 ; i<n ; i++) {
        for(int j=0 ; j<m ; j++) {
            scanf("%1d", &mapp[i][j]);
        }
    }

    for(int k = M(n, m) ; k >= 2 ; k--) {
        for(int i=0 ; i<=n-k ; i++) {
            for(int j=0 ; j<=m-k ; j++) {
                if(N(N(mapp[i][j], mapp[i+k-1][j]),
                    N(mapp[i][j+k-1], mapp[i+k-1][j+k-1]))) {
                    f = P(f, k * k);
                }
            }
        }
    }

    printf("%d\n", f);
    return 0;
}

#include <stdio.h>
int mapp[10][10], w, h;
int ans;
void f(int x, int y) {
    if(x < 1 || x > w || y < 1 || y > h) return;
    if(!mapp[x][y]) return;
    mapp[x][y] = 0;
    for(int i=-1 ; i<=1 ; i++) {
        for(int j=-1 ; j<=1 ; j++) {
            f(x+i, y+j);
        }
    }
}
int main()
{
    scanf("%d %d", &h, &w);
    for(int i=1 ; i<=w ; i++) {
        for(int j=1 ; j<=h ; j++) {
            scanf("%d", &mapp[i][j]);
        }
    }
    for(int i=1 ; i<=w ; i++) {
        for(int j=1 ; j<=h ; j++) {
            if(mapp[i][j]) {
                ans++;
                f(i, j);
            }
        }
    }
    printf("%d", ans);
}

